import{createNativeScene,actor,putKey,validateScene}from'./scene.js';
export function createFinalHandshake(){
const s=createNativeScene('empty');s.name='Handshake · editable V97';s.duration=6;s.sourceOffset=900;s.background='#092843';s.backgroundGradient=true;s.lighting={ambient:.13,exposure:1,environmentStrength:.35,shadowQuality:'high'};s.nodes=s.nodes.filter(n=>n.id!=='floor');
for(const [id,x,yaw,color]of[['final-blue',-.43,70,'#167caf'],['final-coach',.43,-35,'#e5e0cc']]){
 const n=actor(id,id==='final-blue'?'Blue partner':'Cream partner',color,[x,0,0]);n.position[2]=x<0?.24:-.12;n.style='continuous';n.rotation=[0,yaw,0];n.proportions={headSize:1,neckLength:1,shoulderWidth:1.06,armLength:1,legLength:1};n.shape={shoulders:.04,chest:.04,waist:-.03,hips:.03,glutes:.06,thighs:.04,calves:.05,headWidth:.02,jaw:-.04};n.parts.shirt.construction='body-fit';n.parts.trousers.construction='body-fit';n.parts.shirt.ease=.003;n.parts.trousers.ease=.002;n.parts.shirt.roughness=.42;n.parts.trousers.roughness=.35;n.material.roughness=.36;n.handCurl={L:.18,R:.18};
 if(x>0)Object.assign(n.parts.hat,{visible:true,autoFit:true,width:1.08,depth:1.05,height:.95,lift:-.008,tilt:4,roll:-6});
 n.ikTracks={rightHand:[{time:0,value:[x, .87,.14]},{time:.65,value:[x*.45,1.02,.25]},{time:1.1,value:[x<0?-.075:.075,1.07,.23]},{time:1.6,value:[x<0?-.075:.075,1.035,.23]},{time:2.05,value:[x<0?-.075:.075,1.08,.23]},{time:2.5,value:[x<0?-.075:.075,1.045,.23]},{time:3.15,value:[x,.88,.13]}]};
 n.handPoseTracks={R:[{time:0,value:0},{time:.7,value:.5},{time:1.1,value:1},{time:2.5,value:1},{time:3.15,value:0}]};
 n.boneTracks={spine02:[{time:0,value:[0,0,0]},{time:.9,value:[3,x<0?5:-5,0]},{time:2.5,value:[2,x<0?4:-4,0]},{time:3.3,value:[0,0,0]}],head:[{time:0,value:[0,0,0]},{time:1,value:[8,0,0]},{time:2.8,value:[3,0,0]},{time:4,value:[0,0,0]}]};s.nodes.push(n);
}
const camera=s.nodes.find(n=>n.id===s.cameraId);camera.fov=32;
for(const[t,pos,target]of[[0,[.15,1.40,2.9],[0,1.22,0]],[.7,[.08,1.27,2.4],[0,1.12,.08]],[1.15,[.02,1.19,1.25],[0,1.15,.16]],[2.1,[.02,1.19,1.25],[0,1.15,.16]],[2.8,[.15,1.32,2.7],[0,1.08,0]],[3.6,[.15,1.35,2.8],[0,1.10,0]],[5.8,[.15,4.1,2.0],[0,1.1,0]]]){putKey(camera,'position',t,pos);putKey(camera,'target',t,target);}camera.position=[.15,1.3,2.6];camera.target=[0,1.12,0];
Object.assign(s.nodes.find(n=>n.id==='key'),{position:[-2,3,3],intensity:2.8});Object.assign(s.nodes.find(n=>n.id==='fill'),{intensity:.45});Object.assign(s.nodes.find(n=>n.id==='rim'),{position:[1,2,-2],intensity:2.2});validateScene(s);return s;}
export function createFinalTeam(){const s=createNativeScene('empty');s.name='Three independent red anatomical players';s.transparentBackground=true;s.duration=6;s.sourceOffset=915;s.background='#08090b';s.lighting.ambient=.06;s.nodes=s.nodes.filter(n=>n.id!=='floor');for(let i=0;i<3;i++){const n=actor('final-player-'+i,'Red player '+(i+1),'#b71326',[(i-1)*.65,0,i===1?0:.2]);n.proportions.headSize=1;n.headColor='#b71326';n.parts.shirt.color='#b71326';n.parts.trousers.color='#b71326';n.handCurl={L:.15,R:.16};n.boneTracks={head:[{time:0,value:[0,(i-1)*-8,0]},{time:6,value:[0,(i-1)*-6,0]}]};s.nodes.push(n);}const camera=s.nodes.find(n=>n.id===s.cameraId);camera.position=[.3,1.2,4.8];camera.target=[0,1,0];camera.fov=33;putKey(camera,'position',0,[.4,1.2,5.2]);putKey(camera,'position',6,[0,1.2,4.5]);s.nodes.find(n=>n.id==='key').intensity=.6;s.nodes.find(n=>n.id==='rim').color='#ffb34f';s.nodes.find(n=>n.id==='rim').intensity=3;validateScene(s);return s;}
